sys_script_include.script:
var HSBCTradeTaskUtilsPassive = Class.create();
HSBCTradeTaskUtilsPassive.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


    getPositionAvailableMarkets: function() {
        var position_unavailable_markets = gs.getProperty('x_hsb11_mss_c_proc.custody_position_unavailable_markets');
        var tradeId = this.getParameter('sysparm_trade_id');

        var trade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade_passive');
        trade.addQuery('sys_id', tradeId);
        trade.addQuery('owning_business', 'NOT IN', position_unavailable_markets);
        trade.query();
        if (trade.next())
            return true;
        else
            return false;

    },

    checkGMOpsGroupMember: function() {
        var user = this.getParameter('sysparm_user');
        var groupSysId = gs.getProperty('x_hsb11_mss_c_proc.GM_Ops');
        var grMember = new GlideRecord('sys_user_grmember');
        grMember.addEncodedQuery('group=' + groupSysId + '^user=' + user);
        grMember.query();
        if (grMember.next()) {
            return true;
        } else
            return false;
    },


    getSwiftAvailableMarkets: function() {
        var swift_unavailable_markets = gs.getProperty('x_hsb11_mss_c_proc.custody_swift_unavailable_markets');
        var tradeId = this.getParameter('sysparm_trade_id');

        var trade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade_passive');
        trade.addQuery('sys_id', tradeId);
        trade.addQuery('owning_business', 'NOT IN', swift_unavailable_markets);
        trade.query();
        if (trade.next())
            return true;
        else
            return false;


    },

    getTradeID: function() {
        var market = this.getParameter('sysparm_dummy_trade_market');
        var refId = this.getParameter('sysparm_trade_ref_id');
        var sourceSystem = '';

        if (market.indexOf('UK') > -1) {
            sourceSystem = 'GCS';
        } else {
            sourceSystem = 'GHSS'; // source system non UK
        }

        var query = 'trade_idLIKE' + refId + '^owning_business=' + market + '^source_systemLIKE' + sourceSystem;
        var tradeExists = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade_passive');
        tradeExists.addEncodedQuery(query);
        //tradeExists.setLimit(3);
        tradeExists.query();
        if (tradeExists.next()) {
            //gs.log("Inside if " + ctrade.sys_id);
            return tradeExists.sys_id;
        } else
            return '';

    },

    getTrade: function() {
        var tradeSysId = this.getParameter('sysparm_tradeSysId');
        var trade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade_passive');
        if (trade.get(tradeSysId)) {
            return trade.trade_id.toString();
        }
        return '';
    },

    type: 'HSBCTradeTaskUtilsPassive'
});
